#!/bin/sh\n# test_entrypoint.sh – deterministic test for entrypoint.sh\n# Mock rationale: we set QUOTE_INDEX to force a known output without randomness.\n\nset -e\n\nchmod +x ../src/entrypoint.sh\n\nEXPECTED="The sun rose, but the coffee machine stayed dead. Rise and grind, literally."\n\nOUTPUT=$(QUOTE_INDEX=1 ../src/entrypoint.sh)\n\nif [ "$OUTPUT" = "$EXPECTED" ]; then\n  echo "PASS"\n  exit 0\nelse\n  echo "FAIL: expected '$EXPECTED' but got '$OUTPUT'"\n  exit 1\nfi
